def count_sorted_matrix_negatives(grid):
 row=len(grid)-1;column=0;answer=0
 while row>=0 and column<len(grid[0]):
  if grid[row][column]<0:answer+=len(grid[0])-column;row-=1
  else:column+=1
 return answer

